-- Generated by tools/build_basic_data.py from the clean V44 manifest.
-- Run only after Flyway V44+. No users, credentials or business data are copied.
-- Existing populated CMS data is a no-op; partially empty CMS data is rejected.
BEGIN;
SET LOCAL search_path TO cleverchat_dev, public;
SET LOCAL lock_timeout = '10s';
LOCK TABLE tb_role, tb_auth, tb_menu, tb_code, tb_auth_menu_adm IN SHARE ROW EXCLUSIVE MODE;
DO $basic_data$
DECLARE nonempty_tables integer;
BEGIN
  SELECT (EXISTS(SELECT 1 FROM tb_auth))::int + (EXISTS(SELECT 1 FROM tb_menu))::int
       + (EXISTS(SELECT 1 FROM tb_code))::int + (EXISTS(SELECT 1 FROM tb_auth_menu_adm))::int
  INTO nonempty_tables;
  IF nonempty_tables = 4 THEN
    RAISE NOTICE 'Existing CMS data retained. Run check-basic-data.sql to inspect it.';
    RETURN;
  ELSIF nonempty_tables <> 0 THEN
    RAISE EXCEPTION 'Partially populated CMS tables: no changes made. Review/restore the missing data.';
  END IF;

  SELECT v.code,v.description FROM (VALUES
    ('ADMIN', '관리자'),
    ('OPERATOR', '운영자'),
    ('USER', '일반 사용자')) v(code,description)
  WHERE NOT EXISTS(SELECT 1 FROM tb_role r WHERE r.code=v.code)
  ON CONFLICT(code) DO NOTHING;






  PERFORM setval('seq_tb_auth_auth_no', GREATEST(s.last_value,(SELECT max(auth_no) FROM tb_auth)),
      s.is_called OR (SELECT max(auth_no) FROM tb_auth) >= s.last_value) FROM seq_tb_auth_auth_no s;
  PERFORM setval('seq_tb_menu_menu_no', GREATEST(s.last_value,(SELECT max(menu_no) FROM tb_menu)),
      s.is_called OR (SELECT max(menu_no) FROM tb_menu) >= s.last_value) FROM seq_tb_menu_menu_no s;
  PERFORM setval('tb_code_code_no_seq', GREATEST(s.last_value,(SELECT max(code_no) FROM tb_code)),
      s.is_called OR (SELECT max(code_no) FROM tb_code) >= s.last_value) FROM tb_code_code_no_seq s;
  RAISE NOTICE 'Default menus/codes/roles/permissions initialized. User accounts were not modified.';
END $basic_data$;
COMMIT;
